def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1
    for i in range(n-1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
            break
    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from functools import lru_cache
    from collections import defaultdict

    # Build the grid from the grid_values list
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x-1, y-1)] = value

    # Use a 4D memoization to store the results of subproblems
    @lru_cache(None)
    def dp(r1, c1, r2, c2):
        # If either path goes out of bounds or out of the grid, return -infinity
        if r1 >= N or c1 >= N or r2 >= N or c2 >= N:
            return float('-inf')
        # If both paths have reached the bottom-right corner, return the value at that cell
        if r1 == N - 1 and c1 == N - 1:
            return grid[(r1, c1)]
        # Calculate the current cell value that both paths can collect
        current_value = grid[(r1, c1)] if (r1, c1) == (r2, c2) else grid[(r1, c1)] + grid[(r2, c2)]
        # Calculate the maximum value by considering all possible moves for both paths
        maximum = max(dp(r1 + 1, c1, r2 + 1, c2), dp(r1 + 1, c1, r2, c2 + 1),
                      dp(r1, c1 + 1, r2 + 1, c2), dp(r1, c1 + 1, r2, c2 + 1))
        return current_value + maximum

    # Start the dynamic programming process from the top-left corner with both paths
    return dp(0, 0, 0, 0)

def find_number_combinations():
    def is_valid_combination(a, b, c):
        digits = set(str(a) + str(b) + str(c))
        return len(digits) == 9 and '0' not in digits

    combinations = []
    for a in range(123, 368):  # 369 * 3 = 1107, so the first number must be less than 368
        b = 2 * a
        c = 3 * a
        if is_valid_combination(a, b, c):
            combinations.append((a, b, c))

