def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("The value of n should be in the range of 1 to 50, inclusive.")

    factorial = 1
    sum_factorials = 0

    for i in range(1, n + 1):
        factorial *= i
        sum_factorials += factorial

    return sum_factorials

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: A string representing the number string.
    :param N: An integer representing the length of the number string.
    :param K: An integer representing the number of multiplication signs to insert.
    :return: The maximum product that can be obtained by inserting K multiplication signs.
    """
    def split_and_multiply(parts):
        product = 1
        for part in parts:
            if part:  # Avoid multiplying by empty strings
                product *= int(part)
        return product

    def backtrack(start, parts):
        if len(parts) == K + 1:
            if start == N:
                return split_and_multiply(parts)
            else:
                return float('-inf')

        max_product = float('-inf')
        for i in range(start, N - (K + 1 - len(parts)) + 2):
            parts.append(num_str[start:i])
            max_product = max(max_product, backtrack(i, parts))
            parts.pop()

        return max_product

    return backtrack(0, [])

