def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize the DP array with zeros
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the DP array from back to front
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + price * importance)

    # The maximum happiness is the maximum value in the DP array
    return max(dp)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        if coeff > 0 and terms:
            sign = '+'
        elif coeff < 0:
            sign = '-'
        else:
            sign = ''

        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        if degree > 1:
            term = f"{coeff_str}x^{degree}"
        elif degree == 1:
            term = f"{coeff_str}x"
        else:
            term = coeff_str

        terms.append(f"{sign}{term}")

    if not terms:
        return "0"

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def count_partitions(n: int, k: int, x: int) -> int:
    # Base cases
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0

    # Recursive case
    count = 0
    for i in range(x, n - k * x + 1):
        count += count_partitions(n - i, k - 1, i)

    return count

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    if last == 1:
        return 1

    count = 1  # Counting the sequence with just the starting number 'n'
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    if x0 == 0 or y0 % x0 != 0:
        return 0

    quotient = y0 // x0
    count = 0
    a = 1
    while a * a <= quotient:
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        a += 1
    return count

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a mapping for quick lookup of transformation rules
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)
        transform_map[y].add(x)

    # Perform BFS to explore all unique numbers
    queue = deque([str(n)])
    visited = set([str(n)])

    while queue:
        current_number = queue.popleft()

        for i in range(len(current_number)):
            current_digit = int(current_number[i])

            if current_digit in transform_map:
                for new_digit in transform_map[current_digit]:
                    new_number = current_number[:i] + str(new_digit) + current_number[i+1:]

                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            # Skip statements about the day of the week
            if any(day in statement for day in days_of_week):
                continue

            # Determine if the statement is about guilt
            if "is guilty" in statement:
                # Extract the name from the statement
                guilty_name = statement.split(" ")[0]
                if guilty_name == "I" and participant == scenario:
                    # If the statement is "I am guilty" and the participant is the scenario
                    if participant in liar_count:
                        # If the participant is a liar, the statement is false, which is consistent
                        continue
                    else:
                        # If the participant is not a liar, the statement is true, which is consistent
                        continue
                elif guilty_name != "I" and guilty_name == scenario:
                    # If the statement is "X is guilty" and X is the scenario
                    if participant in liar_count:
                        # If the participant is a liar, the statement is false, which is inconsistent
                        return False
                    else:
                        # If the participant is not a liar, the statement is true, which is consistent
                        continue
                else:
                    # The statement is about someone else's guilt, which we don't care about in this scenario
                    continue
            elif "is not guilty" in statement:
                # Extract the name from the statement
                not_guilty_name = statement.split(" ")[0]
                if not_guilty_name == "I" and participant == scenario:
                    # If the statement is "I am not guilty" and the participant is the scenario
                    if participant in liar_count:
                        # If the participant is a liar, the statement is false, which is consistent
                        continue
                    else:
                        # If the participant is not a liar, the statement is true, which is inconsistent
                        return False
                elif not_guilty_name != "I" and not_guilty_name == scenario:
                    # If the statement is "X is not guilty" and X is the scenario
                    if participant in liar_count:
                        # If the participant is a liar, the statement is false, which is consistent
                        continue
                    else:
                        # If the participant is not a liar, the statement is true, which is inconsistent
                        return False
                else:
                    # The statement is about someone else's guilt, which we don't care about in this scenario
                    continue
    return True

def calculate_score(system: int, points: str) -> list:
    game_scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

