def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    cleared = [False] * (l + 1)
    for start, end in areas:
        for i in range(start, end + 1):
            cleared[i] = True
    return sum(1 for is_cleared in cleared if not is_cleared)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array to store whether a certain volume is achievable
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: zero volume is always achievable

    # Iterate over each item's volume
    for volume in volumes:
        # Traverse the DP array backwards to avoid using an item more than once
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding V
    max_achievable_volume = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_achievable_volume = j
            break

    # The minimum remaining space is the difference between V and the maximum achievable volume
    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(m - j + 1, a[i - 1]) + 1):
                dp[i][j + k] = (dp[i][j + k] + dp[i - 1][j]) % MOD

    return dp[n][m]

