def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    pocket_money_per_month = 300

    for month in range(1, 13):
        remaining_after_expenses = pocket_money_per_month - budgets[month - 1]
        if remaining_after_expenses < 100:
            return -month
        savings_this_month = (remaining_after_expenses // 100) * 100
